import {muteBackground} from './audio.js';
import {DB,player,save,uid,unlock,commitRound} from './data.js';
import {createInstructionGate} from './game-instructions.js';
import {ATTRIBUTES,SLOTS,ITEMS,ITEM_BY_ID,ACTIONS,CHAMPIONS,GLADIATOR_DIFFICULTIES,WEAPON_KINDS} from './gladiator-data.js';
import {makeGladiator,equipment,fighterStats,priceFor,buyItem,allocatePoint,xpNeeded,awardBattle,qualifies,makeOpponent,balancedDuel,ArenaBattle,clone,clamp} from './gladiator-core.js';
import {drawGladiator,drawArena,drawMerchant,gladiatorCover} from './gladiator-art.js';
import {GladiatorAudio} from './gladiator-audio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s[0].toUpperCase()+s.slice(1);
export function openGladiator(host,{exit,notify=()=>{},ask=async()=>true,initialPage='setup'}={}){
 const q=s=>host.querySelector(s);let ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],mode='career',duelMode='Quick Duel',custom={level:5,tier:3,weapon:'sword',theme:'sand'},page='setup',draft=null,budget=10,editing=false,selectedItems={},battle=null,champion=null,round=1,series=[0,0],paused=false,disposed=false,awarded=false,aiWait=0,raf=0,last=performance.now(),scene=null,merchantMood='welcome',shopKind='weapon',selectedItem=null,returnPage='hub',startedAt=0;
 const account=id=>{const p=player(id);if(!p)return null;p.gladiatorArena||={version:1,characters:[],selected:null,duels:{wins:0,losses:0,draws:0}};return p.gladiatorArena;};const current=(i=0)=>{const a=account(ids[i]);return a?.characters.find(g=>g.id===(selectedItems[ids[i]]||a.selected))||a?.characters[0];};
 const sound=new GladiatorAudio({muted:()=>DB.settings.muted,...account(ids[0]).audio});const gate=createInstructionGate({game:'gladiator',onBack:exit,onReview:()=>{const prev=paused;paused=true;sound.pause();return()=>{paused=prev;if(!paused){sound.init();sound.startMusic();}};}});
 function persist(){if(!save())notify('Progress could not be saved. Export a backup before closing.','error');}
 function shell(body,back='setup'){window.scrollTo(0,0);page=back==='battle'?'battle':page;host.innerHTML=`<section class="ga-app"><header class="ga-top"><button data-exit>← ARCADE</button><div><small>LITTLE BIG ARCADE</small><h1>Gladiator Arena</h1></div><button data-help>How to Play</button><button data-settings>♫ Settings</button></header>${body}</section>`;q('[data-exit]').onclick=async()=>{const previous=paused;paused=true;if(!battle||battle.phase==='finished'||await ask('Leave this battle? Completed career progress is saved.'))exit();else paused=previous;};q('[data-help]').onclick=()=>gate.acknowledged?gate.review():gate.show({players:ids.filter(Boolean).map(id=>player(id).name),difficulty:GLADIATOR_DIFFICULTIES[current()?.difficulty??1],modeLabel:'Career & local duels'},()=>{});q('[data-settings]').onclick=()=>settings();scene=null;}
 function button(label,fn,cls=''){const b=document.createElement('button');b.textContent=label;b.className=cls;b.onclick=fn;return b;}
 function startGate(fn){gate.show({players:(mode==='career'?ids.slice(0,1):ids).filter(Boolean).map(id=>player(id).name),difficulty:GLADIATOR_DIFFICULTIES[current()?.difficulty??1],modeLabel:mode==='career'?'Career':duelMode},()=>{muteBackground(true);sound.init();sound.startMusic();fn();});}
 function setup(){page='setup';battle=null;shell(`<div class="ga-welcome"><div class="ga-cover">${gladiatorCover()}<span class="ga-ribbon">CREATE · FIGHT · BECOME A LEGEND</span></div><div class="ga-parchment"><h2>A ridiculous hero. A legendary career.</h2><p>Seven champions await. Build your gladiator, learn the distance, manage your energy and win the crowd.</p><div class="ga-form"><label>Adventure<select data-mode><option value="career">Single-player career</option><option value="duel">Two-player duel</option></select></label>${[0,1].map(i=>`<label data-player="${i}">Player ${i+1}<select data-profile="${i}">${DB.profiles.map(p=>`<option value="${p.id}" ${p.id===ids[i]?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`).join('')}<div data-duel><label>Duel rules<select data-duelmode>${['Quick Duel','Best of 3','Best of 5','Custom Battle'].map(s=>`<option>${s}</option>`).join('')}</select></label><div data-custom><label>Balanced level<input type="range" min="1" max="15" value="5" data-level><output data-levelout>5</output></label><label>Gear tier<select data-tier>${[1,2,3,4,5,6,7].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></label><label>Both weapons<select data-weapon>${WEAPON_KINDS.map(([k,l])=>`<option value="${k}" ${k==='sword'?'selected':''}>${l}</option>`).join('')}</select></label><label>Arena<select data-theme>${['sand','stone','dusk','royal'].map(s=>`<option>${s}</option>`).join('')}</select></label></div></div></div><div class="ga-buttons"><button data-play class="ga-primary">PLAY →</button><button data-records>Career & Duel Records</button></div><p class="ga-note">Local profiles · offline play · careers autosave · Normal is the classic challenge</p></div></div>`);q('[data-mode]').value=mode;const vis=()=>{q('[data-player="1"]').hidden=mode==='career';q('[data-duel]').hidden=mode==='career';q('[data-custom]').hidden=duelMode!=='Custom Battle';};vis();q('[data-mode]').onchange=e=>{mode=e.target.value;vis();};for(const el of host.querySelectorAll('[data-profile]'))el.onchange=e=>ids[+el.dataset.profile]=e.target.value;q('[data-duelmode]').value=duelMode;q('[data-duelmode]').onchange=e=>{duelMode=e.target.value;vis();};q('[data-level]').oninput=e=>{custom.level=+e.target.value;q('[data-levelout]').value=custom.level;};q('[data-tier]').onchange=e=>custom.tier=+e.target.value;q('[data-weapon]').onchange=e=>custom.weapon=e.target.value;q('[data-theme]').onchange=e=>custom.theme=e.target.value;q('[data-play]').onclick=()=>{if(mode==='duel'&&(!ids[1]||ids[0]===ids[1])){notify('Choose two different arcade profiles. Add a second profile from the arcade if needed.');return;}DB.active=ids[0];persist();startGate(()=>mode==='career'?current()?hub():creator(0):duelSelect());};q('[data-records]').onclick=records;}
 function creator(index=0,edit=false){page='creator';editing=edit;draft=edit?clone(current(index)):makeGladiator({id:uid(),name:player(ids[index]).name+' the Bold'});budget=edit?draft.skillPoints:10;renderCreator(index);}
 function renderCreator(index){shell(`<div class="ga-creator"><div class="ga-parchment"><h2>${editing?'Style & training':'Create a gladiator'} · ${esc(player(ids[index]).name)}</h2><div class="ga-form"><label>Name<input data-name maxlength="24" value="${esc(draft.name)}"></label><label>Skin<input data-skin type="color" value="${draft.appearance.skin}"></label><label>Hair color<input data-hair type="color" value="${draft.appearance.hair}"></label>${[['hairStyle','Hair',['bald','short','spikes','long','mohawk']],['beard','Facial hair',['none','stubble','moustache','full']],['eyes','Expression',['brave','angry','silly']]].map(([k,l,opts])=>`<label>${l}<select data-appearance="${k}">${opts.map(v=>`<option ${v===draft.appearance[k]?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label>Build<input type="range" min="0.85" max="1.2" step="0.05" data-body value="${draft.appearance.body}"></label>${!editing?`<label>Career difficulty<select data-diff>${GLADIATOR_DIFFICULTIES.map((n,i)=>`<option value="${i}" ${draft.difficulty===i?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</div><button data-random>⚄ Randomize look</button><p data-attribute-note>Choose a build. Every attribute has a purpose.</p><strong data-points>${budget} skill points left</strong><div class="ga-attributes">${Object.entries(ATTRIBUTES).map(([k,desc])=>`<div><button data-info="${k}" title="${desc}">${title(k)}</button><button data-minus="${k}" ${editing?'disabled':''}>−</button><b data-value="${k}">${draft.attributes[k]}</b><button data-plus="${k}">+</button></div>`).join('')}</div><div class="ga-buttons"><button data-create class="ga-primary">${editing?'SAVE CHANGES':'ENTER THE ARENA'} →</button><button data-cancel>Back</button></div></div><div class="ga-preview"><canvas width="1000" height="560" aria-label="Animated gladiator appearance preview"></canvas><p data-stats></p></div></div>`);scene={type:'preview',fighter:draft};const stats=()=>{const s=fighterStats(draft);q('[data-stats]').textContent=`Health ${s.maxHp} · Energy ${s.maxEnergy} · Damage ${Math.round(s.damage)} · Reach ${s.reach}`;q('[data-points]').textContent=`${budget} skill points left`;for(const el of host.querySelectorAll('[data-value]'))el.textContent=draft.attributes[el.dataset.value];for(const el of host.querySelectorAll('[data-plus]'))el.disabled=budget<=0||draft.attributes[el.dataset.plus]>=65;};stats();q('[data-name]').oninput=e=>draft.name=e.target.value.slice(0,24);for(const k of ['skin','hair'])q('[data-'+k+']').oninput=e=>draft.appearance[k]=e.target.value;host.querySelectorAll('[data-appearance]').forEach(el=>el.onchange=e=>draft.appearance[el.dataset.appearance]=e.target.value);q('[data-body]').oninput=e=>draft.appearance.body=+e.target.value;if(q('[data-diff]'))q('[data-diff]').onchange=e=>draft.difficulty=+e.target.value;host.querySelectorAll('[data-info]').forEach(el=>el.onclick=()=>q('[data-attribute-note]').textContent=ATTRIBUTES[el.dataset.info]);host.querySelectorAll('[data-plus]').forEach(el=>el.onclick=()=>{const k=el.dataset.plus;if(budget>0&&draft.attributes[k]<65){draft.attributes[k]++;budget--;stats();}});host.querySelectorAll('[data-minus]').forEach(el=>el.onclick=()=>{const k=el.dataset.minus;if(!editing&&draft.attributes[k]>3){draft.attributes[k]--;budget++;stats();}});q('[data-random]').onclick=()=>{draft.appearance={skin:['#a96749','#d79a66','#e6bc94','#80523c'][Math.floor(Math.random()*4)],hair:['#543228','#bd7733','#e0d1b0'][Math.floor(Math.random()*3)],hairStyle:['short','spikes','long','mohawk','bald'][Math.floor(Math.random()*5)],beard:['none','stubble','moustache','full'][Math.floor(Math.random()*4)],eyes:['brave','angry','silly'][Math.floor(Math.random()*3)],body:.85+Math.floor(Math.random()*8)*.05};renderCreator(index);};q('[data-create]').onclick=()=>{draft.name=draft.name.trim()||'The Nameless';draft.skillPoints=budget;const a=account(ids[index]);if(editing){const i=a.characters.findIndex(g=>g.id===draft.id);a.characters[i]=draft;}else a.characters.push(draft);a.selected=draft.id;selectedItems[ids[index]]=draft.id;persist();if(mode==='duel')duelSelect();else hub();};q('[data-cancel]').onclick=()=>mode==='duel'?duelSelect():current()?hub():setup();}
 function hub(){page='hub';battle=null;const g=current(),a=account(ids[0]);if(!g){creator();return;}const s=fighterStats(g);shell(`<div class="ga-hub"><div class="ga-parchment"><small>${esc(player(ids[0]).name)}’S GLADIATORS</small><h2>${esc(g.name)}</h2><select data-character>${a.characters.map(v=>`<option value="${v.id}" ${g.id===v.id?'selected':''}>${esc(v.name)} · Lv ${v.level}</option>`).join('')}</select><p><b>Level ${g.level}</b> · ${GLADIATOR_DIFFICULTIES[g.difficulty]} · <b>${g.gold} gold</b> · ${g.wins} wins</p><progress value="${g.xp}" max="${xpNeeded(g)}"></progress><small>XP ${g.xp} / ${xpNeeded(g)} · ${g.skillPoints} training points</small><p>Health ${s.maxHp} · Energy ${s.maxEnergy} · Armor ${s.armor}</p><div class="ga-buttons"><button data-fight class="ga-primary">⚔ REGULAR FIGHT</button><button data-weapons>Weaponsmith</button><button data-armor>Armorer</button><button data-train>Appearance & Training ${g.skillPoints?'('+g.skillPoints+')':''}</button><button data-new>Create another gladiator</button><button data-menu>Main menu</button></div><p class="ga-note">${g.difficulty===2?'Hard defeat: lose 8% of unspent gold.':g.difficulty===1?'Defeat still earns training XP and 10 gold.':'Easy defeats earn XP and 20 gold. Unlimited retries.'} Equipment and champions are always kept.</p></div><div class="ga-hub-art"><canvas width="1000" height="560" aria-label="Your gladiator in the coliseum"></canvas><div class="ga-tournaments"><h3>THE SEVEN LAURELS · ${g.champions.length}/7</h3>${CHAMPIONS.map(c=>`<button data-champion="${c.id}" ${g.champions.includes(c.id)||!qualifies(g,c)?'disabled':''}><b>${g.champions.includes(c.id)?'🏆':c.index+1} ${c.cup}</b><span>${esc(c.name)} · Level ${c.level} · ${c.wins} career wins${g.champions.includes(c.id)?' · Won':''}</span></button>`).join('')}</div></div></div>`);scene={type:'preview',fighter:g,theme:'sand'};q('[data-character]').onchange=e=>{a.selected=e.target.value;selectedItems[ids[0]]=e.target.value;persist();hub();};q('[data-fight]').onclick=()=>launchBattle();q('[data-weapons]').onclick=()=>shop('weapon');q('[data-armor]').onclick=()=>shop('armor');q('[data-train]').onclick=()=>creator(0,true);q('[data-new]').onclick=()=>creator();q('[data-menu]').onclick=setup;host.querySelectorAll('[data-champion]').forEach(el=>el.onclick=()=>{const c=CHAMPIONS.find(c=>c.id===el.dataset.champion);if(qualifies(g,c))introChampion(c);});}
 function introChampion(c){page='intro';shell(`<div class="ga-centered ga-parchment"><small>${c.cup.toUpperCase()}</small><h2>${c.name}</h2><canvas width="1000" height="560" aria-label="Tournament champion"></canvas><blockquote>“${c.intro}”</blockquote><p>Level ${c.level} · ${title(c.style)} fighter · Victory earns a laurel and bonus gold.</p><button class="ga-primary" data-enter>ENTER TOURNAMENT</button><button data-back>Back to career</button></div>`);scene={type:'preview',fighter:makeOpponent(current(),c),theme:c.theme};q('[data-enter]').onclick=()=>launchBattle(c);q('[data-back]').onclick=hub;}
 function shop(kind){page='shop';shopKind=kind;merchantMood='welcome';const g=current();selectedItem=ITEMS.find(i=>i.slot===(kind==='weapon'?'weapon':'head')&&i.tier===Math.min(7,Math.ceil(g.level/2)));renderShop();}
 function renderShop(){const g=current(),i=selectedItem,preview=clone(g);if(i)preview.equipped[i.slot]=i.id;const filter=shopKind==='weapon'?'weapon':selectedItem?.slot||'head';shell(`<div class="ga-shop"><div class="ga-parchment"><h2>${shopKind==='weapon'?'Boris’s Weaponsmith':'Marta’s Armory'}</h2><p><b>${g.gold} gold</b> · Level ${g.level} · Charisma discount ${Math.round(Math.min(.25,g.attributes.charisma*.012)*100)}%</p><label>Browse<select data-slot>${(shopKind==='weapon'?['weapon']:SLOTS).map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></label><div class="ga-stock"></div><button data-leave>← Leave shop</button></div><div class="ga-shop-preview"><canvas width="1000" height="560" aria-label="Shopkeeper and equipment preview"></canvas><div class="ga-bubble" data-bubble>Come in! Your next glorious mistake deserves good equipment.</div><div class="ga-parchment"><h3>${i?.name||'Choose an item'}</h3><p>${i?.slot==='weapon'?`Damage ${i.damage} · Reach ${i.reach} · Accuracy ${i.accuracy>=0?'+':''}${i.accuracy} · Push ${Math.round(i.push*100)}%`:`Armor ${i?.armor} · ${i?.block?'Shield block '+i.block+'%':'Independent '+i?.slot+' slot'}`}</p><p>Currently: ${esc(ITEM_BY_ID[g.equipped[i?.slot]]?.name||'None')} → ${esc(i?.name)}</p><strong>${i?priceFor(g,i):0} gold · Requires level ${i?.level}</strong><div class="ga-buttons"><button data-buy class="ga-primary">${g.inventory.includes(i?.id)?'EQUIP OWNED ITEM':'BUY & EQUIP'}</button></div><small>Preview only until you buy or equip. Other armor slots stay as they are.</small></div></div></div>`);scene={type:'shop',fighter:preview};const stock=()=>{const slot=q('[data-slot]').value;q('.ga-stock').innerHTML=ITEMS.filter(i=>i.slot===slot).map(i=>`<button data-item="${i.id}" class="${selectedItem?.id===i.id?'selected':''}"><b>${esc(i.name)}</b><span>Lv ${i.level} · ${g.inventory.includes(i.id)?'OWNED':priceFor(g,i)+' gold'} · ${i.damage?'DMG '+i.damage:'Armor '+i.armor}</span></button>`).join('');host.querySelectorAll('[data-item]').forEach(el=>el.onclick=()=>{selectedItem=ITEM_BY_ID[el.dataset.item];renderShop();q('[data-slot]').value=slot;stock();});};q('[data-slot]').onchange=stock;stock();q('[data-buy]').onclick=()=>{const result=buyItem(g,selectedItem.id);merchantMood=result.ok?'purchase':g.level<selectedItem.level?'level':'poor';q('[data-bubble]').textContent=result.message;if(result.ok){persist();sound.play('coin');renderShop();q('[data-bubble]').textContent=result.message;}};q('[data-leave]').onclick=()=>{merchantMood='leave';q('[data-bubble]').textContent='Back so soon? The arena will send you shopping again!';scene.fighter=g;setTimeout(()=>{if(page==='shop'&&!disposed)hub();},650);};}
 function duelSelect(){page='duel';shell(`<div class="ga-parchment ga-centered"><h2>${duelMode} · Choose your champions</h2><p>Alternating turns on one screen. Balanced duel copies keep both careers safe.</p><div class="ga-duel-picks">${ids.map((id,i)=>{const a=account(id);return `<section><h3>Player ${i+1} · ${esc(player(id).name)}</h3><select data-pick="${i}">${a.characters.map(g=>`<option value="${g.id}" ${g.id===current(i)?.id?'selected':''}>${esc(g.name)}</option>`).join('')||'<option>No gladiator yet</option>'}</select><button data-create-player="${i}">Create Gladiator</button><p>${current(i)?esc(current(i).name):'Create your own silly hero first.'}</p></section>`;}).join('')}</div><p>${duelMode==='Custom Battle'?`Both: Lv ${custom.level}, tier ${custom.tier} ${custom.weapon}, ${custom.theme} arena.`:'Both: level 5, tier 3 balanced gear; equal attributes.'}</p><button data-duel-start class="ga-primary" ${ids.some((_,i)=>!current(i))?'disabled':''}>START DUEL</button><button data-back>Main menu</button></div>`);host.querySelectorAll('[data-pick]').forEach(el=>el.onchange=e=>{const i=+el.dataset.pick;selectedItems[ids[i]]=e.target.value;duelSelect();});host.querySelectorAll('[data-create-player]').forEach(el=>el.onclick=()=>creator(+el.dataset.createPlayer));q('[data-duel-start]').onclick=()=>{series=[0,0];round=1;launchBattle();};q('[data-back]').onclick=setup;}
 function launchBattle(c=null){page='battle';champion=c;paused=false;awarded=false;aiWait=0;const opts=duelMode==='Custom Battle'?custom:{level:5,tier:3,weapon:'sword',theme:'sand'};const fighters=mode==='career'?[current(),makeOpponent(current(),c)]:ids.map((_,i)=>balancedDuel(current(i),opts));battle=new ArenaBattle(fighters,{ai:mode==='career',difficulty:current().difficulty,theme:c?.theme||(mode==='duel'?opts.theme:'sand')});startedAt=performance.now();shell(`<div class="ga-combat"><div class="ga-hud"></div><div class="ga-stage"><canvas width="1000" height="560" aria-label="Turn-based gladiator arena"></canvas><div class="ga-float" aria-live="polite"></div><div class="ga-handoff" hidden></div></div><div class="ga-command"><strong data-turn></strong><div class="ga-actions"></div><button data-pause>Ⅱ PAUSE</button></div><p class="ga-combat-tip">Stay away from the broken arena edges. Shoves can end a battle. Rest restores energy, but gives up an attack.</p></div>`,'battle');scene={type:'battle'};q('[data-pause]').onclick=()=>pauseMenu();renderCombat();}
 function renderCombat(){if(!battle||page!=='battle')return;const f=battle.fighters[battle.turn];q('.ga-hud').innerHTML=battle.fighters.map((f,i)=>`<section class="${battle.turn===i?'active':''}"><b>${mode==='duel'?'P'+(i+1)+' · ':''}${esc(f.name)} <small>Lv ${f.level}</small></b>${[['HEALTH',f.hp,f.stats.maxHp,'hp'],['ENERGY',f.energy,f.stats.maxEnergy,'energy'],['ARMOR',f.armor,Math.max(1,f.stats.armor),'armor']].map(([name,v,max,cls])=>`<div class="ga-meter ${cls}"><span style="width:${v/max*100}%"></span><em>${name} ${Math.ceil(v)}/${max}</em></div>`).join('')}</section>`).join('');q('[data-turn]').textContent=`${mode==='duel'?'Round '+round+' · ':''}${f.name}’s turn · Distance ${Math.round(battle.distance())} · ${battle.phase==='ready'?'Choose an action':battle.phase==='handoff'?'Pass the screen':'Action resolving…'}`;q('.ga-actions').innerHTML=Object.entries(ACTIONS).map(([id,a])=>`<button class="ga-action" data-action="${id}" ${paused||!battle.available(id)||mode==='career'&&battle.turn===1?'disabled':''}><i>${a.icon}</i><b>${a.label}</b><small>${a.cost}⚡${a.accuracy!==undefined?' · '+battle.hitChance(id)+'% hit':''}</small></button>`).join('');host.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{if(paused||mode==='career'&&battle.turn===1)return;if(battle.start(el.dataset.action)){sound.play(el.dataset.action);renderCombat();}});const hand=q('.ga-handoff');hand.hidden=battle.phase!=='handoff';if(!hand.hidden){hand.innerHTML=`<h2>Player ${battle.turn+1} — You’re Up!</h2><p>${esc(f.name)} · Pass the touchscreen</p><button class="ga-primary" data-ready>READY!</button>`;q('[data-ready]').onclick=()=>{if(paused)return;battle.ready();renderCombat();};}}
 function finishBattle(){if(awarded)return;awarded=true;const winner=battle.winner,f=battle.fighters,won=winner===0;let reward=null;if(mode==='career'){reward=awardBattle(current(),{won,champion,enemyLevel:f[1].level});unlock(player(ids[0]),'gladiator-first');if(reward.champion)unlock(player(ids[0]),'gladiator-laurel');if(reward.finished)unlock(player(ids[0]),'gladiator-emperor');commitRound([{id:ids[0],score:won?Math.round(300+f[1].level*40+f[0].hp):0,hits:battle.log.filter(e=>e.actor===f[0].name&&e.damage>0).length,errors:battle.log.filter(e=>e.actor===f[0].name&&['MISS!','DODGED!','BLOCKED!'].includes(e.text)).length,duration:(performance.now()-startedAt)/1000,soloWin:won,details:{characterId:current().id,champion:champion?.id||null,turns:battle.turns}}], {game:'gladiator',difficulty:current().difficulty+1,mode:'solo',learn:false,ruleset:'gladiator-v1',levelId:champion?.id||'regular',competition:'career',challengeKey:'career'});}else{if(winner>=0)series[winner]++;ids.forEach((id,i)=>{const a=account(id);a.duels[winner<0?'draws':winner===i?'wins':'losses']++;if(winner===i)unlock(player(id),'gladiator-duelist');});commitRound(ids.map((id,i)=>({id,score:winner===i?500:0,hits:battle.log.filter(e=>e.actor===f[i].name&&e.damage>0).length,errors:0,duration:(performance.now()-startedAt)/1000,details:{duelMode,round}})),{game:'gladiator',difficulty:2,mode:'versus',learn:false,winnerId:winner<0?null:ids[winner],ruleset:'gladiator-v1',levelId:duelMode,competition:'duel',challengeKey:duelMode});}persist();sound.play(won||mode==='duel'?'victory':'defeat');setTimeout(()=>{if(disposed||page!=='battle')return;const need=duelMode==='Best of 3'?2:duelMode==='Best of 5'?3:1,more=mode==='duel'&&Math.max(...series)<need;page='result';shell(`<div class="ga-centered ga-parchment"><small>${battle.reason.toUpperCase()}</small><h2>${winner<0?'An honorable draw!':esc(f[winner].name)+' wins!'}</h2><canvas width="1000" height="560" aria-label="Battle celebration"></canvas>${mode==='career'?`<h3>${reward.finished?'🏆 IMPERIAL CHAMPION · ALL SEVEN LAURELS':reward.champion?'🏆 '+champion.cup+' WON':won?'THE CROWD ROARS!':'Train, equip and try again.'}</h3><p>+${reward.gold} gold · +${reward.xp} XP${reward.levels?' · Level up! +'+reward.levels*5+' training points':''}</p><p>${champion?esc(won?champion.loseLine:champion.winLine):'Your career has been saved.'}</p><button class="ga-primary" data-next>BACK TO CAREER</button>`:`<h3>${esc(player(ids[0]).name)} ${series[0]} — ${series[1]} ${esc(player(ids[1]).name)}</h3><p>${battle.turns+1} turns · ${more?'First to '+need+' round wins.':'Series complete. Careers preserved.'}</p><button class="ga-primary" data-next>${more?'NEXT ROUND':'PLAY AGAIN'}</button><button data-menu>Main menu</button>`}<details><summary>Battle report</summary><div class="ga-report">${battle.log.map(e=>`<p>${esc(e.actor)} · ${ACTIONS[e.action].label}: ${esc(e.text)}</p>`).join('')}</div></details></div>`);scene={type:'result',fighter:f[winner<0?0:winner],theme:battle.theme};q('[data-next]').onclick=()=>{if(mode==='career')hub();else if(more){round++;launchBattle();}else{series=[0,0];round=1;duelSelect();}};if(q('[data-menu]'))q('[data-menu]').onclick=setup;},800);}
 function pauseMenu(){if(page!=='battle')return;paused=true;sound.pause();q('.ga-handoff').hidden=false;q('.ga-handoff').innerHTML='<h2>Battle paused</h2><button class="ga-primary" data-resume>RESUME</button><button data-pausesettings>Sound settings</button>';q('[data-resume]').onclick=()=>{paused=false;sound.init();sound.startMusic();renderCombat();};q('[data-pausesettings]').onclick=settings;host.querySelectorAll('[data-action]').forEach(b=>b.disabled=true);}
 function settings(){const old=paused;paused=true;sound.pause();const dialog=document.createElement('dialog');dialog.className='ga-settings';dialog.innerHTML=`<h2>Arena sound</h2><label>Music volume<input type="range" min="0" max="0.5" step="0.01" value="${sound.music}" data-music></label><label>Effects volume<input type="range" min="0" max="1" step="0.05" value="${sound.sfx}" data-sfx></label><p>Original synthesized crowd, metal, swishes, footsteps and fanfares. Arcade mute also applies.</p><button>DONE</button>`;document.body.append(dialog);dialog.querySelector('[data-music]').oninput=e=>{sound.music=+e.target.value;account(ids[0]).audio={music:sound.music,sfx:sound.sfx};persist();};dialog.querySelector('[data-sfx]').oninput=e=>{sound.sfx=+e.target.value;account(ids[0]).audio={music:sound.music,sfx:sound.sfx};persist();sound.init();sound.play('block');};const close=()=>{dialog.close();dialog.remove();paused=old;if(!paused&&gate.acknowledged){sound.init();sound.startMusic();}};dialog.querySelector('button').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};dialog.showModal();}
 function records(){page='records';shell(`<div class="ga-parchment ga-centered"><h2>Career & Duel Records</h2>${DB.profiles.map(p=>{const a=p.gladiatorArena;return `<h3>${esc(p.name)}</h3><p>${a?`${a.duels.wins} duel victories · ${a.duels.losses} losses · ${a.duels.draws} draws`:'A fresh arena career awaits.'}</p>${a?.characters.map(g=>`<p><b>${esc(g.name)}</b> · Lv ${g.level} · ${GLADIATOR_DIFFICULTIES[g.difficulty]} · ${g.wins} wins · ${g.losses} losses · ${g.champions.length}/7 laurels · ${g.gold} gold</p>`).join('')||''}`;}).join('')}<button data-back>BACK</button></div>`);q('[data-back]').onclick=setup;}
 function frame(now){if(disposed)return;const dt=Math.min(50,now-last);last=now;if(scene&&q('canvas')){const c=q('canvas').getContext('2d');c.clearRect(0,0,1000,560);drawArena(c,{theme:scene.theme||battle?.theme||'sand',time:now,crowd:page==='result'?1:0});if(scene.type==='battle'&&battle){const z=battle.animation;for(let i=0;i<2;i++){const f=battle.fighters[i],active=z?.index===i,progress=z?clamp(z.elapsed/z.duration,0,1):0;let x=f.x;if(z?.to)x=z.from[i]+(z.to[i]-z.from[i])*clamp((progress-.48)/.45,0,1);drawGladiator(c,f,{x,y:455,scale:1.05,facing:i?-1:1,time:now,action:battle.phase==='finished'?(battle.winner===i?'victory':'defeat'):z&&battle.phase==='animating'?active?z.action:z.impact?z.outcome?.reaction||'idle':'idle':'idle',progress:active?progress:clamp((progress-.48)/.52,0,1)});}if(!paused){if(battle.phase==='animating'){const e=battle.tick(dt);if(e){q('.ga-float').textContent=e.text;q('.ga-float').classList.remove('burst');void q('.ga-float').offsetWidth;q('.ga-float').classList.add('burst');sound.play(e.reaction==='block'?'block':e.damage?'impact':e.reaction==='dodge'?'back':'rest');renderCombat();}if(battle.phase==='finished')finishBattle();else if(battle.phase!=='animating')renderCombat();}else if(battle.phase==='ready'&&mode==='career'&&battle.turn===1){aiWait+=dt;if(aiWait>650){aiWait=0;const a=battle.chooseAI();battle.start(a);sound.play(a);renderCombat();}}}}else{const f=scene.fighter;drawGladiator(c,{...f,equipment:f.equipment||equipment(f)},{x:scene.type==='shop'?710:500,y:455,scale:1.35,time:now,action:scene.type==='result'?'victory':'idle',progress:(now%1200)/1200});if(scene.type==='shop')drawMerchant(c,shopKind,220,455,now,merchantMood);}}raf=requestAnimationFrame(frame);}
 const visibility=()=>{if(document.hidden&&page==='battle')pauseMenu();};document.addEventListener('visibilitychange',visibility);if(initialPage==='records')records();else setup();raf=requestAnimationFrame(frame);return()=>{disposed=true;cancelAnimationFrame(raf);gate.dispose();sound.dispose();muteBackground(false);document.removeEventListener('visibilitychange',visibility);document.querySelectorAll('.ga-settings').forEach(d=>d.remove());host.innerHTML='';};
}
